// ─── File: src/main/java/com/bank/metrics/service/RiskMetricsService.java ───
package com.bank.metrics.service;

import com.bank.metrics.dto.*;
import com.bank.metrics.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class RiskMetricsService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "SAV2001", "RELIANCE", new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "SAV2001", "TCS",      new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "CUR3001", "HDFC",     new BigDecimal("330150"), "SETTLED"),
        new Trade("TRD-004", "SAV2001", "INFY",     new BigDecimal("222037"), "SETTLED"),
        new Trade("TRD-005", "CUR3001", "WIPRO",    new BigDecimal("33664"),  "SETTLED"),
        new Trade("TRD-006", "SAV2001", "RELIANCE", new BigDecimal("123750"), "SETTLED")
    );

    // ═══ TEEING: min + max in ONE pass ═══
    public SalaryRange getAmountRange() {
        return trades.stream()
            .map(Trade::amount)
            .collect(Collectors.teeing(
                Collectors.minBy(Comparator.naturalOrder()),  // downstream 1: min
                Collectors.maxBy(Comparator.naturalOrder()),  // downstream 2: max
                SalaryRange::new));                            // merge: combine
        // One pass: each amount goes to BOTH minBy and maxBy simultaneously
    }

    // ═══ TEEING: count + sum in ONE pass ═══
    public TradeMetrics getCountAndSum() {
        record CountSum(long count, BigDecimal sum) {}

        CountSum cs = trades.stream()
            .map(Trade::amount)
            .collect(Collectors.teeing(
                Collectors.counting(),
                Collectors.reducing(BigDecimal.ZERO, BigDecimal::add),
                CountSum::new));

        return new TradeMetrics(cs.count(), cs.sum(), null, null,
            cs.sum().doubleValue() / cs.count(),
            "teeing(counting, reducing) — count+sum in ONE pass");
    }

    // ═══ TEEING OF TEEING: all 5 metrics in TWO passes (not 5!) ═══
    public TradeMetrics getAllMetrics() {
        // Inner teeing 1: min + max
        // Inner teeing 2: count + sum
        // Outer teeing: combine both inner results + compute average

        record MinMax(Optional<BigDecimal> min, Optional<BigDecimal> max) {}
        record CountSum(long count, BigDecimal sum) {}

        record Combined(MinMax minMax, CountSum countSum) {}

        Combined combined = trades.stream()
            .map(Trade::amount)
            .collect(Collectors.teeing(
                // Inner teeing 1: min + max
                Collectors.teeing(
                    Collectors.minBy(Comparator.naturalOrder()),
                    Collectors.maxBy(Comparator.naturalOrder()),
                    MinMax::new),
                // Inner teeing 2: count + sum
                Collectors.teeing(
                    Collectors.counting(),
                    Collectors.reducing(BigDecimal.ZERO, BigDecimal::add),
                    CountSum::new),
                Combined::new));

        return new TradeMetrics(
            combined.countSum().count(),
            combined.countSum().sum(),
            combined.minMax().min().orElse(BigDecimal.ZERO),
            combined.minMax().max().orElse(BigDecimal.ZERO),
            combined.countSum().sum().doubleValue() / combined.countSum().count(),
            "NESTED teeing: 4 metrics in ONE pass (min+max+count+sum → compute avg)");
    }

    // ═══ COMPARISON: 5 separate streams (wasteful) ═══
    public TradeMetrics getAllMetricsSeparate() {
        List<BigDecimal> amounts = trades.stream().map(Trade::amount).toList();

        long count = amounts.stream().count();                                     // pass 1
        BigDecimal sum = amounts.stream().reduce(BigDecimal.ZERO, BigDecimal::add); // pass 2
        BigDecimal min = amounts.stream().min(Comparator.naturalOrder()).orElse(BigDecimal.ZERO); // pass 3
        BigDecimal max = amounts.stream().max(Comparator.naturalOrder()).orElse(BigDecimal.ZERO); // pass 4
        double avg = sum.doubleValue() / count;                                     // computed from sum/count

        return new TradeMetrics(count, sum, min, max, avg,
            "5 SEPARATE STREAMS — 4 passes over the data (wasteful!)");
    }
}
```

