package com.bank.metrics.controller;

import com.bank.metrics.dto.*;
import com.bank.metrics.service.RiskMetricsService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/metrics")
@RequiredArgsConstructor
public class MetricsController {

    private final RiskMetricsService service;

    @GetMapping("/range")
    public SalaryRange range() { return service.getAmountRange(); }

    @GetMapping("/count-sum")
    public TradeMetrics countSum() { return service.getCountAndSum(); }

    @GetMapping("/all-teeing")
    public TradeMetrics allTeeing() { return service.getAllMetrics(); }

    @GetMapping("/all-separate")
    public TradeMetrics allSeparate() { return service.getAllMetricsSeparate(); }

    @GetMapping("/compare")
    public Map<String, TradeMetrics> compare() {
        return Map.of("teeing", service.getAllMetrics(), "separate", service.getAllMetricsSeparate());
    }
}
