// ─── File: src/test/java/com/bank/metrics/service/TeeingCollectorTest.java ───
package com.bank.metrics.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class TeeingCollectorTest {

    @Test
    void teeingMinAndMax() {
        record MinMax(Optional<Integer> min, Optional<Integer> max) {}

        MinMax result = Stream.of(5, 2, 8, 1, 9, 3)
            .collect(Collectors.teeing(
                Collectors.minBy(Comparator.naturalOrder()),
                Collectors.maxBy(Comparator.naturalOrder()),
                MinMax::new));

        assertThat(result.min()).contains(1);
        assertThat(result.max()).contains(9);
    }

    @Test
    void teeingCountAndSum() {
        record CountSum(long count, int sum) {}

        CountSum result = Stream.of(10, 20, 30)
            .collect(Collectors.teeing(
                Collectors.counting(),
                Collectors.summingInt(Integer::intValue),
                CountSum::new));

        assertThat(result.count()).isEqualTo(3);
        assertThat(result.sum()).isEqualTo(60);
    }

    @Test
    void teeingEmptyStream() {
        record MinMax(Optional<Integer> min, Optional<Integer> max) {}

        MinMax result = Stream.<Integer>empty()
            .collect(Collectors.teeing(
                Collectors.minBy(Comparator.naturalOrder()),
                Collectors.maxBy(Comparator.naturalOrder()),
                MinMax::new));

        assertThat(result.min()).isEmpty();
        assertThat(result.max()).isEmpty();
    }

    @Test
    void nestedTeeing() {
        record Inner1(Optional<Integer> min, Optional<Integer> max) {}
        record Inner2(long count, int sum) {}
        record Combined(Inner1 minMax, Inner2 countSum) {}

        Combined result = Stream.of(10, 20, 30, 40)
            .collect(Collectors.teeing(
                Collectors.teeing(
                    Collectors.minBy(Comparator.naturalOrder()),
                    Collectors.maxBy(Comparator.naturalOrder()),
                    Inner1::new),
                Collectors.teeing(
                    Collectors.counting(),
                    Collectors.summingInt(Integer::intValue),
                    Inner2::new),
                Combined::new));

        assertThat(result.minMax().min()).contains(10);
        assertThat(result.minMax().max()).contains(40);
        assertThat(result.countSum().count()).isEqualTo(4);
        assertThat(result.countSum().sum()).isEqualTo(100);
    }

    @Test
    void teeingWithFilteredDownstreams() {
        record HighLow(long highCount, long lowCount) {}

        HighLow result = Stream.of(100, 200, 300, 400, 500)
            .collect(Collectors.teeing(
                Collectors.filtering(n -> n > 250, Collectors.counting()),
                Collectors.filtering(n -> n <= 250, Collectors.counting()),
                HighLow::new));

        assertThat(result.highCount()).isEqualTo(3);  // 300, 400, 500
        assertThat(result.lowCount()).isEqualTo(2);   // 100, 200
    }

    @Test
    void teeingProducesSameResultAsSeparateStreams() {
        List<Integer> data = List.of(10, 20, 30, 40, 50);

        // Separate:
        Optional<Integer> sepMin = data.stream().min(Comparator.naturalOrder());
        Optional<Integer> sepMax = data.stream().max(Comparator.naturalOrder());

        // Teeing:
        record MinMax(Optional<Integer> min, Optional<Integer> max) {}
        MinMax teeing = data.stream().collect(Collectors.teeing(
            Collectors.minBy(Comparator.naturalOrder()),
            Collectors.maxBy(Comparator.naturalOrder()),
            MinMax::new));

        assertThat(teeing.min()).isEqualTo(sepMin);
        assertThat(teeing.max()).isEqualTo(sepMax);
    }
}
